use crate::{Error, Profile};

/// Supported channel-bed loudspeaker layouts, in decoder channel order.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(usize)]
pub enum BedLayout {
    Stereo,
    Surround51,
    Surround71,
    Surround512,
    Surround514,
    Surround712,
    Surround714,
}

impl BedLayout {
    pub(super) fn speaker_names(self) -> &'static [&'static str] {
        match self {
            Self::Stereo => &["M+030", "M-030"],
            Self::Surround51 => &["M+030", "M-030", "M+000", "LFE1", "M+110", "M-110"],
            Self::Surround71 => &[
                "M+030", "M-030", "M+000", "LFE1", "M+090", "M-090", "M+135", "M-135",
            ],
            Self::Surround512 => &[
                "M+030", "M-030", "M+000", "LFE1", "M+110", "M-110", "U+030", "U-030",
            ],
            Self::Surround514 => &[
                "M+030", "M-030", "M+000", "LFE1", "M+110", "M-110", "U+030", "U-030", "U+110",
                "U-110",
            ],
            Self::Surround712 => &[
                "M+030", "M-030", "M+000", "LFE1", "M+090", "M-090", "M+135", "M-135", "U+045",
                "U-045",
            ],
            Self::Surround714 => &[
                "M+030", "M-030", "M+000", "LFE1", "M+090", "M-090", "M+135", "M-135", "U+045",
                "U-045", "U+135", "U-135",
            ],
        }
    }
    pub fn from_configuration(configuration: u8) -> Result<Self, Error> {
        match configuration {
            1 => Ok(Self::Stereo),
            2 => Ok(Self::Surround51),
            3 => Ok(Self::Surround71),
            7 => Ok(Self::Surround512),
            8 => Ok(Self::Surround514),
            9 => Ok(Self::Surround712),
            10 => Ok(Self::Surround714),
            _ => Err(Error::Unsupported("channel-bed rendering configuration")),
        }
    }
    pub fn from_profile(profile: Profile) -> Result<Self, Error> {
        match profile {
            Profile::ChannelBed { configuration } => Self::from_configuration(configuration),
            _ => Err(Error::Unsupported("object or HOA rendering")),
        }
    }
    pub fn channels(self) -> u16 {
        [2, 6, 8, 8, 10, 10, 12][self as usize]
    }
    pub fn configuration(self) -> u8 {
        [1, 2, 3, 7, 8, 9, 10][self as usize]
    }
    pub(super) fn gains_to(self, output: Self) -> &'static [u8] {
        MATRICES[self as usize * 7 + output as usize]
    }
}

pub(super) fn gain(index: u8) -> f32 {
    f32::from_bits(
        [
            0x3f59999a, 0x00000000, 0x3f800000, 0x3f599130, 0x3f19ddcf, 0xbf19ddcf, 0x3f3504f3,
            0x80000000,
        ][usize::from(index)],
    )
}

